#!/usr/bin/env bash
# StructuredMnistHSQVAE grid (configs generated by scripts/config_generator_hstrees.jl; numbering explained there).
# Outputs: data/HSTreeGenExperiments/<dataset>/<model_type>/seed=<s>/<config>_ID-<n>/ (dataset comes from the config).
# The same config name exists for both datasets, so job names get a dataset tag: unb_ (mnist_clock_unbalanced),
# bal_ (mnist_clock).  DRY_RUN=1 ./global_job_assingment.sh  only prints what would be submitted.
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
EXP_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"

# Uprav jen tyto 4 veci:
# batch 1: dropout 0, α1 λ0.01, β ∈ {1e-5, 1e-3}, npoints ∈ {256, 512}, e_pma_mz ∈ {1, 2}
#   -> c1000, c1002, c1100, c1102, c2000, c2002, c2100, c2102 on both datasets
CONFIGS=(
    configs/mnist_clock_unbalanced_configs/mcd_smhsqvae_c{1,2}{0,1}0{0,2}.yml
    configs/mnist_clock_configs/mcd_smhsqvae_c{1,2}{0,1}0{0,2}.yml
)
SEEDS=(1)
TIME_LIMIT=24
EPOCHS=-1

DRY_RUN=${DRY_RUN:-0}
mkdir -p "${EXP_DIR}/slurms"

for cfg in "${CONFIGS[@]}"; do
    [[ -f "${EXP_DIR}/${cfg}" ]] || { echo "Missing config: ${cfg}" >&2; exit 1; }
    cfg_name="$(basename "${cfg}" .yml)"
    case "${cfg}" in
        *mnist_clock_unbalanced_configs*) tag="unb" ;;
        *mnist_clock_configs*)            tag="bal" ;;
        *)                                tag="x" ;;
    esac
    for seed in "${SEEDS[@]}"; do
        model_dir="${cfg_name}"
        job_name="${tag}_${cfg_name}_s${seed}"
        echo "Submitting ${tag} ${cfg_name}, seed=${seed}"
        if [[ "${DRY_RUN}" == "1" ]]; then
            echo "  sbatch --job-name=${job_name} --chdir ${EXP_DIR} run_smhsqvae_training.sh ${cfg} ${seed} ${TIME_LIMIT} ${model_dir} ${EPOCHS}"
            continue
        fi
        sbatch --job-name="${job_name}" --chdir "${EXP_DIR}" \
            "${SCRIPT_DIR}/run_smhsqvae_training.sh" \
            "${cfg}" "${seed}" "${TIME_LIMIT}" "${model_dir}" "${EPOCHS}"
    done
done


: '
# later batches (generate the configs first), e.g.
# dropout 0.1 twins of batch 1:
CONFIGS=( configs/mnist_clock_unbalanced_configs/mcd_smhsqvae_c{1,2}{0,1}0{1,3}.yml )
# sigmoid β (H = 2), dropout 0, α1 λ0.01:
CONFIGS=( configs/mnist_clock_unbalanced_configs/mcd_smhsqvae_c{1,2}20{0,2}.yml )
    '
